LOCATIONS = [x for xs in AREAS.values() for x in xs]

def today():
    return dt.datetime.now(KST).date()

def default_location(name):
    if name in '만두 떡 아이스크림 냉동피자 얼음'.split(): return '하단 냉동칸'
    if name in '돼지고기 소고기 닭고기 고등어 연어 새우 오징어 조개 멸치'.split(): return '상단 냉동칸'
    if name in '간장 감자 고구마 참치 김 식빵'.split(): return '실온 보관함'
    if name in FOOD_NAMES[16:40]: return '채소칸'
    if name in '마요네즈 케첩 물 주스 두유'.split(): return '문쪽 수납칸'
    if name in FOOD_NAMES[8:16] or name in '베이컨 햄 소시지 어묵 맛살'.split(): return '중단 선반'
    return '상단 선반'

def template(name):
    return dict(id='food-'+str(uuid.uuid5(uuid.NAMESPACE_URL,name)), kind='food',
                name=name, icon=name, location=default_location(name), qty=0,
                purchase=None, expiry=None, expiry_type='소비기한')

def merge_foods(records):
    foods={template(n)['id']:template(n) for n in FOOD_NAMES}
    foods.update({k:v for k,v in records.items() if v.get('kind')=='food'})
    return list(foods.values())

def switched(item):
    item=copy.deepcopy(item)
    if item['qty']>0:
        item['qty']=0
    else:
        item.update(qty=1,purchase=today().isoformat(),expiry=None)
    return item

def expiry_label(item):
    if not item.get('expiry'): return '기한 미입력'
    d=dt.date.fromisoformat(item['expiry'])
    days=(d-today()).days
    suffix='기한 지남' if days<0 else '오늘까지' if days==0 else f'{days}일 남음'
    return f"{item.get('expiry_type','소비기한')} {d:%Y.%m.%d} · {suffix}"

def ics_escape(text):
    return str(text).replace('\\','\\\\').replace('\n','\\n').replace(';','\\;').replace(',','\\,')

def calendar_bytes(foods,hour,minute,previous=True,same=True):
    lines=['BEGIN:VCALENDAR','VERSION:2.0','PRODID:-//Home Fridge//KO','CALSCALE:GREGORIAN']
    now=dt.datetime.now(dt.timezone.utc).strftime('%Y%m%dT%H%M%SZ')
    for f in foods:
        if f.get('qty',0)<=0 or not f.get('expiry'): continue
        due=dt.date.fromisoformat(f['expiry'])
        for days in ([1] if previous else [])+([0] if same else []):
            alarm_date=due-dt.timedelta(days=days)
            start=dt.datetime.combine(alarm_date,dt.time(hour,minute),KST)
            if start<dt.datetime.now(KST): continue
            summary=f"{f['name']} · {f.get('expiry_type','소비기한')} {due:%m/%d}"
            lines += ['BEGIN:VEVENT',f"UID:{f['id']}-{due}-{days}@homefridge",
                      'DTSTAMP:'+now,'DTSTART:'+start.astimezone(dt.timezone.utc).strftime('%Y%m%dT%H%M%SZ'),
                      'DTEND:'+(start+dt.timedelta(minutes=10)).astimezone(dt.timezone.utc).strftime('%Y%m%dT%H%M%SZ'),
                      'SUMMARY:'+ics_escape(summary),'DESCRIPTION:'+ics_escape('포장지와 실제 보관 상태를 확인하세요. 앱과 자동 동기화되지 않습니다.'),
                      'BEGIN:VALARM','TRIGGER:PT0M','ACTION:DISPLAY','DESCRIPTION:'+ics_escape(summary),'END:VALARM','END:VEVENT']
    lines += ['END:VCALENDAR']
    # RFC 5545: fold long lines by UTF-8 byte length, not character length.
    folded=[]
    for line in lines:
        chunk=''
        for char in line:
            if len((chunk+char).encode('utf-8'))>73:
                folded.append(chunk);chunk=' '+char
            else: chunk+=char
        folded.append(chunk)
    return ('\r\n'.join(folded)+'\r\n').encode('utf-8')

def secret(key,default=''):
    try: return st.secrets.get(key,default)
    except (FileNotFoundError,KeyError): return default

class Store:
    def __init__(self):
        self.url=secret('SUPABASE_URL').rstrip('/')
        self.key=secret('SUPABASE_SERVICE_ROLE_KEY')
        if bool(self.url)!=bool(self.key):
            raise ValueError('공유 저장소 연결 정보가 부족해요.')
        self.remote=bool(self.url and self.key)
        if not self.remote:
            Path('data').mkdir(exist_ok=True)
            with sqlite3.connect('data/fridge_v2.db') as db:
                db.execute('create table if not exists records (id text primary key, payload text not null)')
    def api(self,method,**kwargs):
        r=requests.request(method,self.url+'/rest/v1/household_fridge',
            headers={'apikey':self.key,'Authorization':'Bearer '+self.key,
                     'Content-Type':'application/json','Prefer':'resolution=merge-duplicates,return=minimal'},timeout=15,**kwargs)
        r.raise_for_status()
        return r
    def load(self):
        if self.remote:
            result={};offset=0
            while True:
                rows=self.api('GET',params={'select':'id,payload','order':'id','limit':'500','offset':offset}).json()
                result.update({r['id']:r['payload'] for r in rows})
                if len(rows)<500: return result
                offset+=len(rows)
        with sqlite3.connect('data/fridge_v2.db') as db:
            return {k:json.loads(v) for k,v in db.execute('select id,payload from records')}
    def put(self,item):
        if self.remote: self.api('POST',json={'id':item['id'],'payload':item})
        else:
            with sqlite3.connect('data/fridge_v2.db') as db:
                db.execute('insert or replace into records values (?,?)',(item['id'],json.dumps(item,ensure_ascii=False)))

