password=secret('APP_PASSWORD')
if password and not st.session_state.get('authenticated'):
    st.title('우리 집 냉장고')
    with st.form('login'):
        entered=st.text_input('가족 비밀번호',type='password')
        ok=st.form_submit_button('냉장고 열기',use_container_width=True)
    if ok:
        if hmac.compare_digest(entered.encode(),password.encode()):
            st.session_state.authenticated=True;st.rerun()
        else: st.error('비밀번호를 다시 확인해 주세요.')
    st.stop()
try:
    store=Store(); records=store.load()
except Exception:
    st.error('저장소에 연결하지 못했어요. Secrets 설정과 테이블을 확인해 주세요. 다른 저장소에 대신 저장하지 않습니다.')
    st.stop()
if not store.remote:
    st.caption('체험 모드 · 가족 공유와 영구 보존은 설정에서 연결해 주세요.')
elif not password:
    st.error('가족 데이터 보호를 위해 Secrets에 APP_PASSWORD를 설정해 주세요.');st.stop()
for key,value in {'view':'home','room':'냉장실','shelf':'상단 선반','page':0,'undo':None}.items():
    st.session_state.setdefault(key,value)
foods=merge_foods(records)

def go(view):
    st.session_state.view=view;st.rerun()

def persist(item,undo=True):
    try:
        old=next((f for f in foods if f['id']==item['id']),records.get(item['id']))
        store.put(item)
        if undo and old: st.session_state.undo=copy.deepcopy(old)
        st.session_state.pop('edit_form',None)
        st.rerun()
    except requests.RequestException:
        st.error('저장 응답을 확인하지 못했어요. 새로고침해서 반영 여부를 확인해 주세요.')
    except sqlite3.Error:
        st.error('저장하지 못했어요. 잠시 후 다시 시도해 주세요.')

if st.session_state.undo:
    if st.button('↶ 방금 변경 되돌리기',use_container_width=True):
        old=st.session_state.undo
        try: store.put(old);st.session_state.undo=None;st.rerun()
        except (requests.RequestException,sqlite3.Error): st.error('되돌리지 못했어요. 다시 시도해 주세요.')
view=st.session_state.view
if view=='home':
    st.title('우리 집 냉장고')
